INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("様々なミニゲームをご用意してい\nますよ！\nどのミニゲームで遊びますか？", 0, 190801, 1000001, "2030-04-01 14:00:00", 13, "2020-02-15 15:00:00", 1000);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("楽しいミニゲームをご紹介！\nあなたはどのミニゲームで\n遊びますか？", 0, 190801, 1000002, "2030-04-01 14:00:00", 13, "2020-02-15 15:00:00", 1000);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("こちらは{0}ルピで\n販売中！\nぜひ購入して\n遊んでくださいね！", 0, 190801, 1001001, "2030-04-01 14:00:00", 13, "2020-02-15 15:00:00", 1001);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("動くハートに合わせてタップ！\nシズルさんとエリコさんの\nチョコレートケーキ作りを\nお手伝いしましょう！", 0, 190801, 1002001, "2030-04-01 14:00:00", 12, "2020-02-15 15:00:00", 1002);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("クウカさんを引っ張ってより遠く\nへ飛ばしてあげましょう！\n色々なハプニングでクウカさんに\nエクスタシーを届けましょう！", 0, 190801, 1003001, "2030-04-01 14:00:00", 11, "2020-02-15 15:00:00", 1003);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("左右をタップしてマジムンを倒し\nましょう！\n放て！\n琉球犬アラウンドシュート！", 0, 190801, 1004001, "2030-04-01 14:00:00", 3, "2020-02-15 15:00:00", 1004);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("パネルをタップしてドラゴンズ\nネストのみなさんと一緒に\nしりとり対決をしませんか？\nおしりに「ん」はご法度です。", 0, 190801, 1005001, "2030-04-01 14:00:00", 7, "2020-02-15 15:00:00", 1005);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("素早い動きのネズミに合わせ、\nタップで撃退！\nやる気のリンさんと一緒に\n大切なチーズを守りましょう！", 0, 190801, 1006001, "2030-04-01 14:00:00", 2, "2020-05-31 12:00:00", 1006);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("ミサトさんや部員のみなさんと\nバッティングの特訓ですよ！\nホームランを目指して、ボールを\nタイミングよく打ち返しましょう", 0, 190801, 1007001, "2030-04-01 14:00:00", 4, "2020-08-15 15:00:00", 1007);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("カルミナメダルを使って、\n応援グッズをゲットしましょう！\nメダルはルピを使って\n交換できますよ。\n", 0, 190801, 1008001, "2030-04-01 14:00:00", 6, "2021-08-31 12:00:00", 1008);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("食べたプリンはプリンノート\nで確認してみましょう！\nプリンの材料はルピを使って\n購入できますよ。", 0, 190801, 1009001, "2030-04-01 14:00:00", 13, "2021-12-18 15:00:00", 1009);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("チームでクイズに挑みましょう！\nソロで自分の実力を試すか、マル\nチで仲間と一緒に遊ぶか、好きな\nモードを選んでくださいね♪", 0, 190801, 1010001, "2030-04-01 14:00:00", 4, "2022-02-15 15:00:00", 1010);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("３つのラウンドを駆け抜け、\n総合１位を目指しましょう！\n参加者の皆さんの特徴や、\nＧＰの特徴にも注目です♪", 0, 190801, 1011001, "2030-04-01 14:00:00", 6, "2022-07-18 15:00:00", 1011);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("キャルさん、スズナさんと一緒に\nクイズでお勉強しましょう！\n放課後の教室で二人きりって…\nなんだかドキドキしますね♪", 0, 190801, 1012001, "2030-04-01 14:00:00", 6, "2023-09-18 15:00:00", 1012);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("魔物の討伐任務にいざ行軍！\nエリコさん、マコトさんの\n頼もしい背中は、\n新兵さんたちの憧れですね♪", 0, 190801, 1013001, "2030-04-01 14:00:00", 6, "2024-04-18 15:00:00", 1013);
INSERT INTO `v1_636c72be4ab289c59ebd4dfed7a6fa7c5c556d454b9324c21e864724279f7339` VALUES ("バンディ・シスターズのみなさん\nと戦車バトルに挑戦です！\nパーツやメンバーの組み合わせで\nマシンの特徴が変化しますよ♪", 0, 190801, 1014001, "2030-04-01 14:00:00", 6, "2024-11-18 15:00:00", 1014);
